const FILES=[{"id":"FIL-EFFB9834","name":"F0106-PD-rebar-original.pdf","sha256":"ae8b16439650526a5ef6e1975c852fa38c2ab4466cd73ab725a47bcb32a6b655","size":23871472,"stages":["PD"],"pageCount":139,"registeredAt":"2026-10-17T23:08:21.223Z","review":null},{"id":"FIL-4D91EF2A","name":"F0139-RD-rebar-original.pdf","sha256":"d59c225e75d1e0227f08869b31165bd93bf85ed4b1da005c3e86ebc27023b73f","size":2298875,"stages":["RD"],"pageCount":22,"registeredAt":"2026-10-17T23:08:21.504Z","review":null}] as SourceFileSummary[];
const concrete=REAL.execution.results[32],rebar=REAL.execution.results[33];
const concreteFacts=REAL.execution.observations.filter(f=>f.attribute==='CONCRETE_CLASS');
const pd=concreteFacts.find(f=>f.stage==='PD')!,rd=concreteFacts.find(f=>f.stage==='RD')!;
const data=(rows:MatrixAtomicResult[]=[concrete],facts:MatrixObservation[]=concreteFacts):MatrixExecutionRead=>({...clone(REAL),execution:{...clone(REAL.execution),results:clone(rows),observations:clone(facts)}});
const item=(d:MatrixExecutionRead=data(),files:SourceFileSummary[]=FILES)=>buildMatrixReviewWorklist(d,files)[0];
const group=(entry:ReturnType<typeof item>,stage:string)=>entry.groups.find(g=>g.stage===stage)!;
const referenced=():MatrixAtomicResult=>({...clone(concrete),expectedObservationId:pd.id,actualObservationId:rd.id});
const html=(d:MatrixExecutionRead=data(),files:SourceFileSummary[]=FILES)=>renderToStaticMarkup(createElement(MatrixReviewWorklist,{data:d,files,onSelect:()=>{},onSource:()=>{}}));
const text=(node:any):string=>{if(node==null||typeof node==='boolean')return'';if(typeof node==='string'||typeof node==='number')return String(node);if(Array.isArray(node))return node.map(text).join('');if(isValidElement(node))return text((node as React.ReactElement<any>).props.children);return'';};
const buttons=(node:any):React.ReactElement<any>[]=>{const result:React.ReactElement<any>[]=[];const walk=(n:any)=>{if(!isValidElement(n))return;const e=n as React.ReactElement<any>;if(e.type==='button')result.push(e);React.Children.forEach(e.props.children,walk);};walk(node);return result;};

describe('immutable saved scalar review worklist',()=>{
 it('real saved KR055 exposes all7PD+1RD, KR057 exact1PD+1RD refs',()=>{
  const list=buildMatrixReviewWorklist(REAL,FILES),c=list.find(x=>x.resultIndex===32)!,r=list.find(x=>x.resultIndex===33)!;
  assert.equal(list.length,63);assert.equal(c.result.reasonCode,'AMBIGUOUS_FACTS');assert.equal(c.rule!.parameterCode,'KR-055');
  assert.equal(group(c,'PD').kind,'MATCHING_FACTS');assert.equal(group(c,'PD').facts.length,7);assert.equal(group(c,'RD').facts.length,1);
  assert.deepEqual(new Set(c.groups.flatMap(g=>g.facts.map(f=>f.id))),new Set(concreteFacts.map(f=>f.id)));
  assert.equal(group(r,'PD').kind,'REFERENCED_FACT');assert.equal(group(r,'RD').kind,'REFERENCED_FACT');assert.deepEqual(r.groups.flatMap(g=>g.facts.map(f=>f.id)),[rebar.expectedObservationId,rebar.actualObservationId]);
 });
 it('all63 abstentions retain distinct stable immutable keys and result indices',()=>{
  const a=buildMatrixReviewWorklist(REAL,FILES),b=buildMatrixReviewWorklist(clone(REAL),clone(FILES));assert.deepEqual(a.map(v=>v.resultIndex),Array.from({length:63},(_,i)=>i));assert.equal(new Set(a.map(v=>v.key)).size,63);assert.deepEqual(a.map(v=>v.key),b.map(v=>v.key));
 });
 it('identical repeated result rows are not collapsed',()=>{
  const list=buildMatrixReviewWorklist(data([concrete,clone(concrete),clone(concrete)]),FILES);assert.equal(list.length,3);assert.deepEqual(list.map(x=>x.resultIndex),[0,1,2]);assert.equal(new Set(list.map(x=>x.key)).size,3);
 });
 it('only successful missing/notcomparable/clarification rows enter',()=>{
  const rows=['MISSING_EVIDENCE','NOT_COMPARABLE','CLARIFICATION_REQUIRED','CANDIDATE','NEGATIVE_VERIFIED'].map(machineStatus=>({...clone(concrete),machineStatus}as MatrixAtomicResult));rows.push({...clone(concrete),executionStatus:'FAILED'});
  assert.deepEqual(buildMatrixReviewWorklist(data(rows),FILES).map(v=>v.resultIndex),[0,1,2]);assert.equal(buildMatrixReviewWorklist(data([{...concrete,machineStatus:'CANDIDATE'}]),FILES).length,0);
 });
 it('nonnull forged reference never falls back to seven convenient PD facts',()=>{
  const row=referenced();row.expectedObservationId='f'.repeat(64);const e=item(data([row]));assert.equal(group(e,'PD').kind,'INVALID_REFERENCE');assert.deepEqual(group(e,'PD').facts,[]);assert.equal(group(e,'RD').kind,'REFERENCED_FACT');
 });
 it('duplicate referenced IDs are invalid even if byte-identical',()=>{
  const e=item(data([referenced()],[pd,clone(pd),rd]));assert.equal(group(e,'PD').kind,'INVALID_REFERENCE');assert.deepEqual(group(e,'PD').facts,[]);
 });
 it('wrong stage, attribute, unit or parameter exact refs are invalid without fallback',()=>{
  for(const mutate of [(f:any)=>f.stage='RD',(f:any)=>f.attribute='WORKING_REINFORCEMENT_CLASS',(f:any)=>f.unit='m',(f:any)=>f.parameterCodes=['KR-057'],(f:any)=>delete f.parameterCodes]){const f=clone(pd);mutate(f);const e=item(data([referenced()],[f,rd]));assert.equal(group(e,'PD').kind,'INVALID_REFERENCE');assert.deepEqual(group(e,'PD').facts,[]);}
 });
 it('a duplicate ID with mismatching attributes cannot escape uniqueness test',()=>{
  const bad={...clone(pd),attribute:'OTHER',unit:'OTHER'};const e=item(data([referenced()],[pd,bad,rd]));assert.equal(group(e,'PD').kind,'INVALID_REFERENCE');
 });
 it('null refs enumerate every exact match and discard duplicate IDs entirely',()=>{
  const bads=[{...clone(pd),id:'1'.repeat(64),attribute:'OTHER'},{...clone(pd),id:'2'.repeat(64),unit:'m'},{...clone(pd),id:'3'.repeat(64),parameterCodes:['KR-057']},{...clone(pd),id:'4'.repeat(64),stage:'ID'}]as MatrixObservation[];
  const e=item(data([concrete],[...concreteFacts,...bads,clone(pd)]));assert.equal(group(e,'PD').kind,'MATCHING_FACTS');assert.equal(group(e,'PD').facts.length,6);assert.ok(!group(e,'PD').facts.some(f=>f.id===pd.id));assert.equal(group(e,'RD').facts.length,1);
 });
 it('missing required RD stage stays explicit MISSING_FACT',()=>{
  const e=item(data([concrete],concreteFacts.filter(f=>f.stage==='PD')));assert.equal(group(e,'RD').kind,'MISSING_FACT');assert.deepEqual(group(e,'RD').facts,[]);
 });
 it('ruleId/version/parameter/variant drift is invalid installed rule, no invented rule',()=>{
  for(const change of [{ruleId:'not-installed'},{ruleVersion:'999'},{parameterCode:'KR-057'},{comparisonVariant:'NOT_INSTALLED'}]){const e=item(data([{...clone(concrete),...change}as MatrixAtomicResult]));assert.equal(e.invalidRule,true);assert.equal(e.rule,null);assert.equal(e.groups.flatMap(g=>g.facts).length,0);}
 });
 it('PD_ID and RD_ID rules use exact required stages, never PD/RD convenience',()=>{
  // Existing rule explicitly supports PD_ID; native ID copy only tests navigation, not real evidence.
  const row=clone(REAL.execution.results[0]);row.comparisonVariant='PD_ID';row.expectedObservationId=null;row.actualObservationId=null;
  const e=item(data([row],[]));assert.equal(e.invalidRule,false);assert.deepEqual(e.groups.map(g=>g.stage),['PD','ID']);assert.ok(e.groups.every(g=>g.kind==='MISSING_FACT'));const rdId={...clone(concrete),comparisonVariant:'RD_ID'}as MatrixAtomicResult;const other=item(data([rdId],[]));assert.equal(other.invalidRule,false);assert.deepEqual(other.groups.map(g=>g.stage),['RD','ID']);
 });
 it('files missing or mismatching preserve matching facts but cannot grant source authority',()=>{
  const nofiles=item(data(),[]),mismatch=item(data(),FILES.map(f=>({...f,sha256:'f'.repeat(64)})));assert.equal(group(nofiles,'PD').facts.length,7);assert.equal(group(mismatch,'PD').facts.length,7);
 });
 it('malformed locator id,sha,page,block and box are not actionable references',()=>{
  const changes=[(f:any)=>f.id='not-hash',(f:any)=>f.sourceSha256='not-hash',(f:any)=>f.pageNumber=0,(f:any)=>f.pageNumber=1.2,(f:any)=>f.pageNumber=Number.MAX_SAFE_INTEGER+1,(f:any)=>f.blockId='',(f:any)=>f.bbox={x:NaN,y:0,width:.1,height:.1},(f:any)=>f.bbox={x:-.1,y:0,width:.1,height:.1},(f:any)=>f.bbox={x:.9,y:0,width:.2,height:.1},(f:any)=>f.bbox={x:0,y:0,width:0,height:.1}];
  for(const mutate of changes){const f=clone(pd);mutate(f);const row=referenced();row.expectedObservationId=f.id;const e=item(data([row],[f,rd]));assert.equal(group(e,'PD').kind,'INVALID_REFERENCE');assert.equal(group(e,'PD').facts.length,0);}
 });
 it('never mutates saved execution, presentation, coverage, observations or source reviews',()=>{
  const d=clone(REAL),f=clone(FILES),before=clone([d,f]);buildMatrixReviewWorklist(d,f);matrixReviewFactSource(pd,f);html(d,f);assert.deepEqual([d,f],before);
 });
});

describe('exact source ID and SHA lookup',()=>{
 it('unique ID + exact source SHA resolves only original file',()=>{assert.deepEqual(matrixReviewFactSource(pd,FILES),FILES.find(f=>f.id===pd.sourceFileId));});
 it('same SHA on other file ID never resolves',()=>{assert.equal(matrixReviewFactSource(pd,FILES.map(f=>({...f,id:'OTHER-'+f.id}))),undefined);});
 it('same ID changed bytes never resolves',()=>{assert.equal(matrixReviewFactSource(pd,FILES.map(f=>({...f,sha256:'0'.repeat(64)}))),undefined);});
 it('duplicate file ID blocks actions even if only one SHA matches',()=>{const exact=FILES.find(f=>f.id===pd.sourceFileId)!;for(const extra of [clone(exact),{...clone(exact),sha256:'0'.repeat(64)}])assert.equal(matrixReviewFactSource(pd,[...FILES,extra]),undefined);});
 it('fact/file invalid SHA cannot satisfy each other',()=>{const fact={...clone(pd),sourceSha256:'bad'};const files=FILES.map(f=>({...f,sha256:'bad'}));assert.equal(matrixReviewFactSource(fact,files),undefined);});
});

describe('read-only review worklist presentation and events',()=>{
 it('SSR renders frozen reason and review checklist without automatic missing-proof diagnosis',()=>{
  const d=data();const before=clone(d),markup=html(d);assert.match(markup,/Что нужно для сравнения/);assert.match(markup,/Причина сохранённого результата: AMBIGUOUS_FACTS/);assert.match(markup,/Все подходящие факты стадии PD: 7\. Пара автоматически не выбрана\./);assert.match(markup,/Все подходящие факты стадии RD: 1\. Пара автоматически не выбрана\./);assert.match(markup,/Условия для проверки по оригиналу/);
  const e=item(d);for(const key of e.rule!.requiredContext)assert.ok(markup.includes(key),key);assert.deepEqual(d,before);assert.doesNotMatch(markup.replace(/<[^>]*>/g,' '),/Проверено автоматически|qualified|Нарушений нет|NO_VIOLATION|Машинное предупреждение|80%|100%/);
 });
 it('SSR missing stage says review cannot create a measurement',()=>{assert.match(html(data([concrete],[pd])),/Нет исходного факта стадии RD\. Ручная привязка не создаёт отсутствующее значение\./);});
 it('SSR invalid saved ref discloses substitution disabled',()=>{const row=referenced();row.expectedObservationId='f'.repeat(64);const markup=html(data([row]));assert.match(markup,/Ссылка исходного результата не подтверждена\. Автоматическая подстановка отключена\./);});
 it('SSR referenced rows label frozen result references',()=>{assert.match(html(data([referenced()])),/Факт из сохранённого результата/);});
 it('missing source SHA disables both actions but retains raw fact text',()=>{
  const d=data([referenced()],[pd,rd]),f=FILES.map(v=>({...v,sha256:'f'.repeat(64)}));const markup=html(d,f);assert.match(markup,/Файл с исходным SHA не подтверждён\. Действия недоступны\./);assert.ok(markup.includes('disabled'));const tree=MatrixReviewWorklist({data:d,files:f,onSelect:()=>{throw Error('unexpected action');},onSource:()=>{throw Error('unexpected source');}});assert.ok(buttons(tree).length>0);assert.ok(buttons(tree).every(b=>b.props.disabled));
 });
 it('render invokes no callbacks and exact explicit clicks carry original fact+installed rule/source',()=>{
  const selections:any[]=[],sources:any[]=[],d=data([referenced()],[pd,rd]),f=clone(FILES),before=clone([d,f]);const tree=MatrixReviewWorklist({data:d,files:f,onSelect:(fact,ruleId)=>selections.push([fact,ruleId]),onSource:file=>sources.push(file)});assert.equal(selections.length,0);assert.equal(sources.length,0);
  const bs=buttons(tree),open=bs.filter(b=>text(b.props.children)==='Открыть факт и правило'),source=bs.filter(b=>text(b.props.children)==='Проверить источник');assert.equal(open.length,2);assert.equal(source.length,2);open[0].props.onClick();source[0].props.onClick();assert.deepEqual(selections,[[pd,concrete.ruleId]]);assert.deepEqual(sources,[{id:pd.sourceFileId,sha256:pd.sourceSha256}]);assert.deepEqual([d,f],before);
 });
 it('only technical/candidate/negative rows produce no actionable list',()=>{
  const d=data([{...clone(concrete),machineStatus:'CANDIDATE'},{...clone(concrete),machineStatus:'NEGATIVE_VERIFIED'},{...clone(concrete),executionStatus:'FAILED'}]);const markup=html(d);assert.doesNotMatch(markup,/Открыть факт и правило|Проверить источник|AMBIGUOUS_FACTS/);
 });
});

describe('SSR isolation and original text boundary',()=>{
 it('SSR of all63 saved rows performs no API fetch or selection fanout',()=>{
  const fetch=vi.spyOn(globalThis,'fetch').mockImplementation(()=>{throw Error('unexpected API fanout');});const calls:any[]=[];
  try{const markup=renderToStaticMarkup(createElement(MatrixReviewWorklist,{data:REAL,files:FILES,onSelect:(...a)=>calls.push(a),onSource:(...a)=>calls.push(a)}));assert.ok(markup.includes('Что нужно для сравнения'));assert.equal(fetch.mock.calls.length,0);assert.equal(calls.length,0);}finally{fetch.mockRestore();}
 });
 it('invalid immutable saved address disables handlers as well as buttons',()=>{
  for(const changed of [{contentHash:'not-content-hash'},{checkId:''}]){const d={...data([referenced()],[pd,rd]),...changed};const called:any[]=[];const tree=MatrixReviewWorklist({data:d,files:FILES,onSelect:(...a)=>called.push(a),onSource:(...a)=>called.push(a)});const bs=buttons(tree);assert.equal(bs.length,4);assert.ok(bs.every(b=>b.props.disabled));bs.forEach(b=>b.props.onClick());assert.equal(called.length,0);}
 });
 it('full Unicode source raw text stays escaped and visible even when source actions are disabled',()=>{
  const fact={...clone(pd),rawText:'Полная исходная строка <script>keep literal</script> & хвост\u202f😀'};const d=data([referenced()],[fact,rd]);const markup=html(d,[]);assert.ok(markup.includes('Полная исходная строка &lt;script&gt;keep literal&lt;/script&gt; &amp; хвост\u202f😀'));assert.ok(!markup.includes('<script>keep literal</script>'));assert.match(markup,/Файл с исходным SHA не подтверждён/);
 });
});
